old:
function lightChip(a, opts){
 const o = opts || {}, d = deliveryOf(a.key || a), L = LIGHT[d.state];
 const title = d.where === 'rental'
 ? `${L.word} — on site: the Coates rental system has it on hire from ${fmtDate(d.rental.from)}${d.rental.from_time ? ' ' + d.rental.from_time : ''}${d.rental.numbers.length ? ' (asset no. ' + d.rental.numbers.filter(n => String(n).toUpperCase() !== 'MISCITEM').join(', ') + ')' : ''}. Nobody has set a light; set one to override it.`
 : d.recorded
 ? `${L.word} — ${L.label.toLowerCase()}, set ${fmtStamp(d.set_at)} by ${d.by || 'unnamed'}${d.where === 'local' ? ` (${LW()})` : d.where === 'rental' ? ' (rental system)' : ' (committed)'}`
 : 'No delivery record — nobody has recorded a delivery for this reference yet. That is not the same as a record saying it is not here.';
 return `<span class="tl ${d.recorded ? L.c : 'none'}${d.recorded && d.where === 'rental' ? ' hire' : ''}" role="img" title="${esc(title)}" aria-label="${esc(title)}"><i></i>${
 o.full ? (d.recorded ? esc(L.label) + (d.where === 'rental' ? ' <span class="w">on hire</span>' : '') : 'No delivery record') : ''}${
 o.eta && d.eta ? ` <span class="eta" title="planned time to site">${esc(d.eta)}</span>` : ''}</span>`;
}

new:
function lightChip(a, opts){
 const o=opts||{},v=deliveryView(a),d=v.d;
 const title=v.said;
 return `<span class="tl ${v.c}${d.recorded&&d.where==='rental'?' hire':''}" role="img" title="${esc(title)}" aria-label="${esc(title)}"><i></i>${
 o.full?esc(v.short):''}${o.eta&&d.eta?` <span class="eta" title="planned time to site">${esc(d.eta)}</span>`:''}</span>`;
}
